import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation, gql } from '@apollo/client';
import { useAuth } from '../../context/AuthContext';
import './Login.css';

const LOGIN_MUTATION = gql`
  mutation Login($username: String, $email: String, $password: String!) {
    login(username: $username, email: $email, password: $password) {
      token
      user {
        id
        username
        email
        role
        scopes
      }
    }
  }
`;

const Login = () => {
  const [loginInput, setLoginInput] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loginType, setLoginType] = useState('username'); // 'username' or 'email'
  const { login } = useAuth();
  const navigate = useNavigate();

  const [loginMutation, { loading }] = useMutation(LOGIN_MUTATION, {
    onCompleted: (data) => {
      if (data?.login?.token && data?.login?.user) {
        login(data.login.user, data.login.token);
        navigate('/dashboard', { replace: true });
      } else {
        setError('Invalid response from server');
      }
    },
    onError: (err) => {
      if (err.networkError) {
        setError('Cannot connect to server. Please ensure the backend server is running.');
      } else {
        // Show specific error messages
        const errorMsg = err.message || 'Login failed';
        setError(errorMsg);
      }
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');

    if (!loginInput || !password) {
      setError('Please enter username/email and password');
      return;
    }

    // Determine if input is email or username
    const isEmail = loginInput.includes('@');
    const variables = isEmail 
      ? { email: loginInput, password }
      : { username: loginInput, password };

    loginMutation({ variables });
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <h1>🚚 TMS</h1>
          <h2>Transportation Management System</h2>
          <p>Sign in to continue</p>
        </div>
        <form onSubmit={handleSubmit} className="login-form">
          {error && <div className="error-message">{error}</div>}
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              id="username"
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Enter username"
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter password"
              required
            />
          </div>
          <button type="submit" className="login-button" disabled={loading}>
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>
        {process.env.REACT_APP_SHOW_DEMO_CREDENTIALS !== 'false' && (
          <div className="login-demo">
            <p><strong>Note:</strong></p>
            <p>Create your first user via GraphQL Playground</p>
            <p style={{ fontSize: '11px', marginTop: '8px' }}>
              Visit: http://localhost:4000/graphql
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Login;
